def char_concat(word):
    def process_pair(left, right, index):
        return left + right + str(index + 1)

    def split_word(word):
        length = len(word)
        if length % 2 == 0:
            return word[:length // 2], word[length // 2:]
        else:
            return word[:length // 2], word[length // 2 + 1:]

    def concatenate_pairs(left, right):
        result = []
        min_length = min(len(left), len(right))
        for i in range(min_length):
            result.append(process_pair(left[i], right[-(i + 1)], i))
        return ''.join(result)

    left, right = split_word(word)
    return concatenate_pairs(left, right)
