def find_rank(scores, score):
    left, right = 0, len(scores) - 1
    rank = len(scores) + 1
    while left <= right:
        mid = (left + right) // 2
        if scores[mid] == score:
            rank = mid + 1
            right = mid - 1
        elif scores[mid] < score:
            rank = mid + 1
            right = mid - 1
        else:
            left = mid + 1
    return rank

