        n = len(arr)
        if n <= 2:
            return 0

        def is_arithmetic_progression(diff, arr):
            for i in range(2, n):
                if arr[i] - arr[i - 1] != diff:
                    return False
            return True

        def find_min_changes(arr):
            min_changes = float('inf')
            for i in range(n):
                for j in range(i + 1, n):
                    diff = arr[j] - arr[i]
                    new_arr = arr[:]
                    new_arr[i] = arr[j] - diff
                    if is_arithmetic_progression(diff, new_arr):
                        changes = sum(1 for x, y in zip(arr, new_arr) if x != y)
                        min_changes = min(min_changes, changes)
                    diff = arr[i] - arr[j]
                    new_arr = arr[:]
                    new_arr[j] = arr[i] + diff
                    if is_arithmetic_progression(diff, new_arr):
                        changes = sum(1 for x, y in zip(arr, new_arr) if x != y)
                        min_changes = min(min_changes, changes)
            return min_changes

        return find_min_changes(arr)

    return calculate_min_changes(arr)
