def shortest_to_char(s, c):
    if not s or c not in s:
        return []

    n = len(s)
    result = [0] * n

    # Calculate distances from left to right
    last_c_index = -n
    for i in range(n):
        if s[i] == c:
            last_c_index = i
        result[i] = i - last_c_index

    # Calculate distances from right to left
    last_c_index = 2 * n
    for i in range(n-1, -1, -1):
        if s[i] == c:
            last_c_index = i
        result[i] = min(result[i], last_c_index - i)

    return result
