from itertools import combinations_with_replacement

def generate_partitions(n):
    partitions = []
    for r in range(1, n + 1):
        for subset in combinations_with_replacement(range(1, n + 1), r):
            if sum(subset) == n:
                partitions.append(subset)
    return partitions

def count_distinct_partitions(partitions):
    distinct_partitions = set()
    for partition in partitions:
        sorted_partition = tuple(sorted(partition))
        distinct_partitions.add(sorted_partition)
    return len(distinct_partitions)

def find_max_partitions(partitions):
    max_partitions = 0
    max_boxes = 0
    for partition in partitions:
        if len(partition) > max_boxes:
            max_boxes = len(partition)
            max_partitions = 1
        elif len(partition) == max_boxes:
            max_partitions += 1
    return max_partitions, max_boxes

def combs_non_empty_boxesII(n):
    partitions = generate_partitions(n)
    total_distributions = count_distinct_partitions(partitions)
    max_distributions, max_boxes = find_max_partitions(partitions)
    return [total_distributions, max_distributions, max_boxes]

